#include <datamunge/optim/bayesian_optimization.hpp>
#include <algorithm>
#include <random>
#include <stdexcept>
namespace datamunge::optim { BayesianOptimization::BayesianOptimization(BayesianOptimizationOptions o):options_(o){} double BayesianOptimization::optimize(ArbitraryFunction& f,std::vector<double>& x,const std::vector<double>& lo,const std::vector<double>& hi,BayesianSurrogate& s)const{if(lo.size()!=hi.size()||lo.size()!=x.size())throw std::invalid_argument("BayesianOptimization: bounds must match coordinates");std::mt19937_64 rng(options_.seed);std::uniform_real_distribution<double> u(0,1);std::vector<std::vector<double>> p;std::vector<double> v;auto draw=[&](){std::vector<double> q(x.size());for(std::size_t j=0;j<q.size();++j){if(!(lo[j]<hi[j]))throw std::invalid_argument("BayesianOptimization: invalid bounds");q[j]=lo[j]+u(rng)*(hi[j]-lo[j]);}return q;};for(std::size_t i=0;i<std::max<std::size_t>(1,options_.initial_samples);++i){auto q=draw();p.push_back(q);v.push_back(f.evaluate(q));}for(std::size_t it=0;it<options_.max_iterations;++it){s.fit(p,v);double best=*std::min_element(v.begin(),v.end()),score=-1e300;auto q=draw();for(int k=0;k<128;++k){auto z=draw();double a=s.acquisition(z,best);if(a>score){score=a;q=std::move(z);}}p.push_back(q);v.push_back(f.evaluate(q));}auto i=static_cast<std::size_t>(std::min_element(v.begin(),v.end())-v.begin());x=p[i];return v[i];}}
